-- V161 -- aria:reconciliation: add a Print Copy button.
--
-- Per the reference table's own "Dispatch Front Office" row: quantity/GRN
-- checking on this screen needs a print copy. Uses PrintButton (registered
-- in page_element_catalog as a real ACTION component -- unlike DataTable/
-- LineChart/TelemetryGauge, which the catalog itself flags as
-- "PLACEHOLDER -- not implemented", PrintButton carries no such flag) bound
-- to the existing 'gate-pass' print_template (print_template.code, already
-- configured with vehicle/flow/status plus a Weighment section showing
-- W1/W2/W3 and Total Unloaded -- exactly the data this screen is about). No
-- new print template needed.
--
-- gatePassId is added to the gpNumber picker's onChangeFill (gate_pass.id,
-- already selected by the picker's own optionsSource -- just wasn't wired to
-- a form field before) so PrintButton's idFrom=prop has a real id to print.
--
-- This page is shared with M10.TankerInbound -- the added button is neutral
-- (same gate_pass print copy makes sense for that workflow too), so no
-- flow-variant gating needed here, unlike the earlier PackUnload-only field
-- additions on this same page.
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Unload Reconciliation", "span": 12, "subtitle": "Reconcile the unloaded quantity against the order. Within tolerance proceeds; a difference goes to the manager.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "GatePass", "joins": [{"entity": "WorkflowInstance", "as": "wi", "on": "gate_pass.workflow_instance_id = wi.id"}, {"entity": "WeighmentCaptureDetail", "as": "wcd", "on": "wcd.workflow_instance_id = gate_pass.workflow_instance_id", "fields": ["wcd.w1_weight_kg as w1WeightKg", "wcd.w2_weight_kg as w2WeightKg"]}], "filter": {"and": [{"field": "wi.assigned_role", "op": "eq", "value": "Dispatch"}, {"field": "wi.status", "op": "eq", "value": "OPEN"}]}, "select": ["id", "gp_number"], "sort": [{"field": "gp_number", "dir": "desc"}]}, "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "flow_variant_code": "flow_variant_code", "first_weight_kg": "w1WeightKg", "second_weight_kg": "w2WeightKg", "gatePassId": "id"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "first_weight_kg", "label": "First Weight (kg)", "type": "number", "readOnly": true}, {"name": "second_weight_kg", "label": "Second Weight (kg)", "type": "number", "readOnly": true}, {"name": "variance_display_kg", "label": "Variance (kg) — auto", "type": "number", "readOnly": true, "computedFrom": "#form.first_weight_kg - #form.second_weight_kg"}, {"name": "variance_reason", "label": "Variance reason (if any)", "type": "textarea"}, {"name": "grn_status", "label": "GRN Status", "type": "select", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload''", "options": [{"label": "Pending", "value": "GRN_PENDING"}, {"label": "Completed", "value": "GRN_COMPLETED"}, {"label": "Not Required", "value": "GRN_NOT_REQUIRED"}, {"label": "Exception", "value": "GRN_EXCEPTION"}]}, {"name": "grn_number", "label": "GRN Number", "type": "text", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''"}, {"name": "grn_date", "label": "GRN Date", "type": "date", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_COMPLETED''"}, {"name": "grn_not_required_reason", "label": "Reason GRN Not Required", "type": "textarea", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_NOT_REQUIRED''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_NOT_REQUIRED''"}, {"name": "grn_exception_reason", "label": "GRN Exception Reason", "type": "textarea", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_EXCEPTION''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload'' && #form.grn_status == ''GRN_EXCEPTION''"}, {"name": "grn_updated_by", "label": "GRN Updated By", "type": "text", "visibleWhen": "#form.flow_variant_code == ''M10.PackUnload''", "requiredWhen": "#form.flow_variant_code == ''M10.PackUnload''"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Reconciled — Within Tolerance", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary", "submitValues": {"withinTolerance": "YES"}}, {"kind": "WorkflowActionButton", "label": "⚠ Difference → Manager", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "error", "submitValues": {"withinTolerance": "NO"}}]}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "PrintButton", "printCode": "gate-pass", "idFrom": "prop", "id": "{{form.gatePassId}}", "label": "🖨 Print Copy"}]}]}]}]}'
WHERE pd.code = 'aria:reconciliation' AND pv.body_json NOT LIKE '%PrintButton%';
